#!/usr/bin/env python3
"""Recompute compact non-choice ground truth for CSX-071_Q1."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-071_Q1"
EVENT_ID = "CSX-071"
INCH_TO_MM = 25.4

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_package_json.evidence_inventory.reports_0_.url.html",
    "data/event_reports/event_reports_004_Locked_event_anchor_Post-Tropical_Cyclone_Ida_NYC_flash_flood.json",
    "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
]


def repo_root() -> Path:
    here = Path(__file__).resolve()
    for parent in [here.parent, *here.parents]:
        package_dir = parent / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
        if package_dir.is_dir():
            return parent
    raise FileNotFoundError(f"Could not locate local data for {EVENT_ID}")


def read_json(package_dir: Path, rel_path: str) -> Any:
    return json.loads((package_dir / rel_path).read_text(encoding="utf-8"))


def extract_report_anchors(html: str) -> dict[str, Any]:
    compact = re.sub(r"\s+", " ", html)
    hour_match = re.search(
        r"Central Park measured its wettest hour on record\s*--\s*([0-9.]+)\" "
        r"between ([^<.]+?) on September 1, 2021",
        compact,
    )
    if not hour_match:
        raise ValueError("Could not extract Central Park hourly rainfall anchor")
    regional_match = re.search(r"amounts in the northern Mid-Atlantic States peaked just above ([0-9.]+)\"", compact)
    if not regional_match:
        raise ValueError("Could not extract regional peak lower-bound rainfall anchor")
    return {
        "central_park_record_hour_inches": float(hour_match.group(1)),
        "central_park_record_hour_window": hour_match.group(2).strip(),
        "central_park_record_hour_date": "2021-09-01",
        "regional_peak_lower_bound_inches": float(regional_match.group(1)),
        "regional_peak_bound_phrase": "just above",
    }


def gridded_metric(stats: dict[str, Any], max_key: str, mean_key: str, local_hour_mm: float) -> dict[str, float]:
    max_mm = float(stats[max_key])
    mean_mm = float(stats[mean_key])
    return {
        "max_mm": max_mm,
        "mean_mm": mean_mm,
        "max_to_mean_ratio": max_mm / mean_mm,
        "central_hour_to_grid_max_ratio": local_hour_mm / max_mm,
    }


def rounded_grids(grids: dict[str, dict[str, float]]) -> dict[str, dict[str, float]]:
    return {
        name: {
            "max_to_mean_ratio": round(values["max_to_mean_ratio"], 3),
            "central_hour_to_grid_max_ratio": round(values["central_hour_to_grid_max_ratio"], 3),
        }
        for name, values in grids.items()
    }


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Requested JSON answer",
                "points": 4,
                "description": "Returns the requested compact JSON with the local hourly value, regional lower bound, regional ratio, all three gridded entries, final label, and one-sentence interpretation.",
                "partial_credit": "Minor field-name or nesting differences are acceptable when every required value and conclusion is present.",
            },
            {
                "name": "Central Park hourly conversion",
                "points": 4,
                "description": "Computes 3.47 inches as 88.138 mm and reports the one-hour intensity as 88.138 mm/h for September 1, 2021.",
                "partial_credit": "Credit is reduced for coarse rounding, missing units, or omitting the one-hour intensity statement.",
            },
            {
                "name": "Regional lower-bound ratio",
                "points": 3,
                "description": "Computes 10 inches as 254.0 mm and the Central Park-hour to regional lower-bound ratio as 0.347.",
                "partial_credit": "Partial credit is earned for one correct value or a correct setup with a small arithmetic error.",
            },
            {
                "name": "Gridded max-to-mean ratios",
                "points": 4,
                "description": "Computes ERA5-Land, GPM IMERG, and CHIRPS max-to-mean ratios as 2.519, 2.574, and 2.065 within tolerance.",
                "partial_credit": "Partial credit is earned when two sources are correct or all sources are attempted with small calculation errors.",
            },
            {
                "name": "Local-hour to grid-maximum ratios",
                "points": 3,
                "description": "Computes Central Park-hour to grid-maximum ratios as 0.693, 0.644, and 0.754 for ERA5-Land, GPM IMERG, and CHIRPS.",
                "partial_credit": "Partial credit is earned when two ratios are correct or all three are directionally correct but outside tolerance.",
            },
            {
                "name": "Computed final interpretation",
                "points": 2,
                "description": "Identifies the final label as short_duration_urban_rainfall_burst or an equivalent concise label tied to the conversions and scale ratios.",
                "partial_credit": "Partial credit is earned for a directionally correct label that is too wordy or insufficiently tied to the computed values.",
            },
        ],
    }


def main() -> None:
    package_dir = repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    event = read_json(package_dir, "metadata/event.json")
    locked = read_json(
        package_dir,
        "data/event_reports/event_reports_004_Locked_event_anchor_Post-Tropical_Cyclone_Ida_NYC_flash_flood.json",
    )
    report_html = (package_dir / "data/event_reports/event_reports_001_package_json.evidence_inventory.reports_0_.url.html").read_text(
        encoding="utf-8",
        errors="ignore",
    )
    report = extract_report_anchors(report_html)
    era5 = read_json(package_dir, "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json(package_dir, "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json(package_dir, "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json")

    central_inches = report["central_park_record_hour_inches"]
    regional_inches = report["regional_peak_lower_bound_inches"]
    central_mm = central_inches * INCH_TO_MM
    regional_peak_lower_bound_mm = regional_inches * INCH_TO_MM
    final_label = "short_duration_urban_rainfall_burst"
    interpretation = (
        "The Central Park one-hour intensity is large enough relative to event-scale gridded maxima to anchor "
        "the NYC diagnosis in a local hourly burst, while the broader maxima provide scale context."
    )

    grids = {
        "era5_land": gridded_metric(
            era5["stats"],
            "precipitation_sum_mm_max",
            "precipitation_sum_mm_mean",
            central_mm,
        ),
        "gpm_imerg": gridded_metric(
            gpm["stats"],
            "gpm_event_precip_mm_max",
            "gpm_event_precip_mm_mean",
            central_mm,
        ),
        "chirps": gridded_metric(
            chirps["stats"],
            "chirps_event_precip_mm_max",
            "chirps_event_precip_mm_mean",
            central_mm,
        ),
    }

    primary_gt = {
        "central_park_hour_mm_per_h": round(central_mm, 3),
        "regional_peak_lower_bound_mm": round(regional_peak_lower_bound_mm, 3),
        "central_hour_to_regional_ratio": round(central_inches / regional_inches, 3),
        "gridded": rounded_grids(grids),
        "final_label": final_label,
        "interpretation": interpretation,
    }

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "numeric_diagnosis",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event_window": {
                "start_date": locked["temporal_window"]["start_date"],
                "end_date": locked["temporal_window"]["end_date"],
            },
            "central_park_record": {
                "inches": central_inches,
                "mm": central_mm,
                "window": report["central_park_record_hour_window"],
                "date": report["central_park_record_hour_date"],
            },
            "regional_peak_lower_bound": {
                "inches": regional_inches,
                "phrase": report["regional_peak_bound_phrase"],
                "mm": regional_peak_lower_bound_mm,
            },
            "gridded_raw": grids,
            "tolerances": {"precip_mm": 0.01, "ratio": 0.01},
        },
        "rubric": build_rubric(),
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{locked['temporal_window']['start_date']} to {locked['temporal_window']['end_date']}",
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }

    output = Path(__file__).with_name("computed_gt.json")
    output.write_text(json.dumps(result, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
